# Reflection:
# The error indicates that a file already exists at the given file_path.
# I need to set the `overwrite` parameter to True to overwrite the existing file.
# I will correct this by setting the `overwrite` parameter to True in the `create_file` API call.

supervisor_profile = apis.supervisor.show_profile()
supervisor_passwords = {
    account_password["account_name"]: account_password["password"]
    for account_password in apis.supervisor.show_account_passwords()
}
spotify_access_token = apis.spotify.login(
    username=supervisor_profile["email"], password=supervisor_passwords["spotify"]
)["access_token"]
playlist_library = [
    item
    for page_index in range(0, 10)
    for item in apis.spotify.show_playlist_library(
        page_index=page_index, access_token=spotify_access_token
    )
]
library_song_ids = set()
for playlist in playlist_library:
    library_song_ids |= set(playlist["song_ids"])
library_songs = [apis.spotify.show_song(song_id=song_id) for song_id in library_song_ids]
csv_content = "title,artists\n"
for song in library_songs:
    title = song["title"]
    artists = "|".join(artist["name"] for artist in song["artists"])
    csv_content += f"{title},{artists}\n"
file_path = "/backup/spotify_songs.csv"
file_system_access_token = apis.file_system.login(
    username=supervisor_profile["email"], password=supervisor_passwords["file_system"]
)["access_token"]
apis.file_system.create_file(
    file_path=file_path, content=csv_content, access_token=file_system_access_token, overwrite=True
)
gmail_access_token = apis.gmail.login(
    username=supervisor_profile["email"], password=supervisor_passwords["gmail"]
)["access_token"]
phone_access_token = apis.phone.login(
    username=supervisor_profile["phone_number"],
    password=supervisor_passwords["phone"],
)["access_token"]
husband_email = next(
    contact["email"]
    for contact in apis.phone.search_contacts(
        access_token=phone_access_token, query="husband"
    )
)
apis.gmail.send_email(
    email_addresses=[husband_email],
    subject="Spotify Songs Backup",
    body="Please find the attached backup of my Spotify songs.",
    attachment_file_paths=[file_path],
    file_system_access_token=file_system_access_token,
    access_token=gmail_access_token,
)
apis.supervisor.complete_task(status="success")

